B.OL=new A.dQ("line","Line follower","Line follower","Robotics","Intermediate","Follow a dark line with the IR line sensor.","Follow a line with IR sensors","RoboCore V2",'// Line follower\n// Steers toward the line using the IR line sensor.\n#include <RoboCoreMotors.h>\n#include <RoboCoreSensors.h>\n\nRoboCoreMotors motors;\nLineSensor line;\n\nconst int BASE_SPEED = 45;\nconst float GAIN = 30.0;\n\nvoid setup() {\n  Serial.begin(115200);\n  motors.begin();\n  line.begin();\n}\n\nvoid loop() {\n  // line.read() returns -1.0 (line far left) to 1.0 (far right)\n  float pos = line.read();\n  int turn = pos * GAIN;\n  motors.drive(BASE_SPEED + turn, BASE_SPEED - turn);\n  Serial.print("line=");\n  Serial.println(pos, 2);\n  delay(50);\n}\n',null,B.Wd,"LineFollower",null,null)
